function renderLavori(t){const a=document.getElementById("lavori-container");a.innerHTML="";const s=t.reduce((t,a)=>(t[a.status]||(t[a.status]=[]),t[a.status].push(a),t),{});[{status:"In Corso",colorTitle:"#3FBFFF",bgClass:"bg-surface"},{status:"Terminati 2026",colorTitle:"text-gray-900",bgClass:"bg-white/50"},{status:"Terminati 2025",colorTitle:"text-gray-900",bgClass:"bg-white/50"},{status:"Terminati 2024",colorTitle:"text-gray-900",bgClass:"bg-white/50"},{status:"Terminati 2023",colorTitle:"text-gray-900",bgClass:"bg-white/50"}].forEach(t=>{const e=s[t.status];if(!e||0===e.length)return;const n=`\n      <section class="section-padding ${t.bgClass}" data-animate="fade-up">\n        <div class="max-w-7xl mx-auto px-6">\n          <div class="text-center mb-16" data-animate="fade-up">\n            ${"In Corso"===t.status?`<h2 class="text-4xl font-bold" style="color: #3FBFFF; margin-bottom: 1.5rem;">Lavori ${t.status}</h2>`:`<h2 class="text-3xl font-bold text-gray-900 mb-4">Lavori ${t.status}</h2>`}\n            <div class="animated-divider mx-auto" aria-hidden="true"></div>\n          </div>\n          <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-16 stagger-children" data-stagger="0.12">\n            ${e.map(a=>`\n              <div class="glass-effect rounded-2xl p-8 border hover-tilt" data-animate="fade-up" style="border-color: #3FBFFF30;">\n                <div class="flex items-start space-x-4">\n                  <div class="w-3 h-3 rounded-full mt-2 animate-pulse" style="background-color: #3FBFFF;"></div>\n                  <div>\n                    ${"In Corso"===t.status?`<h3 class="text-2xl font-bold mb-2" style="color: #3FBFFF;">${a.title}</h3>`:`<h3 class="text-xl font-bold text-gray-900 mb-2">${a.title}</h3>`}\n                    <p class="text-gray-600 mb-2">${a.description}</p>\n                    <p class="text-gray-400">${a.location}</p>\n                  </div>\n                </div>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n      </section>\n    `;a.innerHTML+=n}),"function"==typeof initAnimations&&initAnimations()}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("lavori-container")&&fetch("/data/lavori.json").then(t=>t.json()).then(t=>{renderLavori(t.projects)}).catch(t=>console.error("Error loading Lavori data:",t))});